function sendMomo(q,customReply){
  const c=$('chat'),s=cur;beep(920);
  c.insertAdjacentHTML('beforeend',`<div class="m me"><div><div class="bb">${esc(q)}</div><div class="mread">Read</div></div></div>`);
  c.insertAdjacentHTML('beforeend',`<div class="m" id="typ"><div class="bb dots"><span></span><span></span><span></span></div></div>`);c.scrollTop=c.scrollHeight;
  setTimeout(()=>{
    const t=$('typ');if(t)t.remove();if(cur!==s)return;
    beep(1120);
    const f=(s.PersonalName||s.Name.split(' ').pop());
    const ans=customReply||(
      /makan|lapar|kopi|kue/i.test(q)?`Wah, kebetulan sekali! Ayo ke kantin Schale bersama, Sensei~`:
      /patroli|misi|tugas|kerja/i.test(q)?`Siap, Sensei! ${f} akan langsung bersiap untuk tugas berikutnya!`:
      /halo|hai|pagi|siang|sore|malam/i.test(q)?`Halo juga, Sensei! Senang bisa mengobrol denganmu hari ini.`:
      /suka|sayang|hebat|keren/i.test(q)?`E-Eh?! Sensei selalu mengatakan hal yang bikin salah tingkah saja...`:
      `Mengerti, Sensei! Terima kasih sudah mengabari ${f} ya~`
    );
    c.insertAdjacentHTML('beforeend',bub(s,esc(ans)));c.scrollTop=c.scrollHeight
  },750);
}
