function renderLau(){
  const q=$('lq').value.toLowerCase().trim();
  const out=[];
  S.forEach(s=>{if(!q||[s.Name,s.PathName,loc('School',s.School),loc('Club',s.Club)].join(' ').toLowerCase().includes(q))out.push({t:'stu',id:s.Id,name:s.Name,sub:loc('School',s.School)+' · '+loc('Club',s.Club),ic:img(s.Id,'icon'),fb:fb(s.Id,'icon'),mono:monoTxt(s.Name)})});
  if(rLoaded){for(const c in R)(R[c]||[]).forEach(r=>{if(!q||rname(r).toLowerCase().includes(q))out.push({t:'raid',id:r.Id,cat:c,name:rname(r),sub:RC[c],ic:rsrc(r)[0]||'',fb:rsrc(r).slice(1).join('|'),mono:rmono(r)})})}
  if(RM){RM.filter(e=>!isPerm2099(e)).forEach(e=>{if(!q||e.name.toLowerCase().includes(q))out.push({t:'evt',id:e.id,kind:e.kind,name:e.name,sub:KIND[e.kind]||e.kind,ic:e.icon,mono:e.name[0]||'E'})})}
  lauItems=out.slice(0,18);lauIdx=0;
  $('ll').innerHTML=lauItems.length?lauItems.map((x,i)=>`<button class="lr${i===0?' on':''}" data-i="${i}">${x.ic?`<img alt="" referrerpolicy="no-referrer" src="${esc(x.ic)}" data-fb="${esc(x.fb||'')}" data-mono="${esc(x.mono||'?')}" onerror="imgFb(this)">`:`<span class="mono">${esc(x.mono||'?')}</span>`}<div><b>${esc(x.name)}</b><small>${esc(x.sub)}</small></div><span class="ltag">${x.t==='stu'?'Murid':x.t==='raid'?'Raid':'Event'}</span></button>`).join(''):'<p class="empty">Tidak ada hasil ditemukan.</p>';
}
function pickLau(i){
  const x=lauItems[i];if(!x)return;beep(960);closeLau();
  if(x.t==='stu'){go('stu');select(x.id)}
  else if(x.t==='raid'){go('raid');rcat=x.cat;renderCats();rfilter();rselect(x.id)}
  else{
    if(x.kind==='raid'){const m=rmatch(x.name);if(m){go('raid');rcat=m.c;renderCats();rfilter();rselect(m.r.Id);return}}
    eKind=x.kind;history.replaceState(null,'','#event-'+encodeURIComponent(x.id));go('evt');if(eLoaded){renderEvCtl();efilter();evOpen(x.id)}
  }
}
