/* Bentuk Material You + auto-crop */
const N=40;
const poly=fn=>{const P=[];for(let i=0;i<N;i++){const t=i/N*2*Math.PI,r=fn(t);P.push([Math.cos(t)*r,Math.sin(t)*r])}const m=Math.max(...P.flat().map(Math.abs));return P.map(([x,y])=>`${(50+x/m*50).toFixed(1)}% ${(50+y/m*50).toFixed(1)}%`).join(',')};
const pg=(n,mix)=>t=>{const a=2*Math.PI/n,d=(((t+Math.PI/2)%a)+a)%a-a/2;return 1-mix+mix*Math.cos(Math.PI/n)/Math.cos(d)};
const SH=[t=>1,t=>1+.12*Math.cos(6*t),t=>1+.07*Math.cos(9*t),t=>1+.2*Math.cos(4*t),t=>1+.06*Math.cos(12*t),t=>1/Math.pow(Math.abs(Math.cos(t))**4+Math.abs(Math.sin(t))**4,.25),pg(5,.55),pg(6,.5),pg(3,.5),t=>1/Math.sqrt(Math.cos(t)**2+(Math.sin(t)/.78)**2)].map(poly);
let shI=-1;
function setShape(id){const n=SH.length,k=(id||0)%(n-1);shI=shI<0?(id||0)%n:(shI+1+k)%n;document.documentElement.style.setProperty('--sh',SH[shI])}
