const crop=new Map();let heroTok=0;
const loadImg=(src,cors)=>new Promise((ok,no)=>{const i=new Image();if(cors)i.crossOrigin='anonymous';i.onload=()=>ok(i);i.onerror=no;i.src=src});
async function smartCrop(id,ty){
  const k=id+ty;if(crop.has(k))return crop.get(k);
  let im=null,out=null;
  const corsList=[`${CDN}/images/student/${ty}/${id}.webp`,`${RAWH}/images/student/${ty}/${id}.webp`];
  for(const u of corsList){try{im=await loadImg(u,true);break}catch(e){}}
  if(im)try{
    const W=im.naturalWidth,H=im.naturalHeight,sc=Math.min(1,400/W),w=Math.max(1,Math.round(W*sc)),hh=Math.max(1,Math.round(H*sc));
    const c=document.createElement('canvas');c.width=w;c.height=hh;const x=c.getContext('2d');x.drawImage(im,0,0,w,hh);
    const d=x.getImageData(0,0,w,hh).data;let l=w,t=hh,r=0,b=0,csx=0,cn=0,cl=false;
    for(let y=0;y<hh;y++)for(let xx=0;xx<w;xx++)if(d[(y*w+xx)*4+3]>24){csx+=xx;cn++;if(xx<l)l=xx;if(xx>r)r=xx;if(y<t)t=y;if(y>b)b=y}
    if(r>l&&b>t){const px=Math.round(.025*w),py=Math.round(.025*hh);l=Math.max(0,l-px);t=Math.max(0,t-py);r=Math.min(w-1,r+px);b=Math.min(hh-1,b+py);
      const bw=r-l,bh=b-t,cap=bh*1.1;if(bw>cap&&cn){const cx=csx/cn;let nl=Math.round(cx-cap/2);nl=Math.max(l,Math.min(nl,r-cap));l=nl;r=Math.round(nl+cap);cl=true}
      if((r-l)/w<.97||(b-t)/hh<.97){const sx=l/sc,sy=t/sc,sw=(r-l)/sc,sh=(b-t)/sc,o=document.createElement('canvas');o.width=Math.round(sw);o.height=Math.round(sh);o.getContext('2d').drawImage(im,sx,sy,sw,sh,0,0,o.width,o.height);
        const uu=await new Promise(res=>o.toBlob(bl=>res(bl?URL.createObjectURL(bl):null),'image/png'));out=uu?{u:uu,cl}:null}}
  }catch(e){}
  crop.set(k,out);return out}

