const initHash=location.hash;
let page='home',R={},R_RAW=null,R_RAWp=null,rcat='Raid',rview=[],rcur=null,rterr=null,rLoaded=false,rBusy=false;
const RC={Raid:'Total Assault',TimeAttack:'Grand Assault',WorldRaid:'World Raid'};
const first=x=>Array.isArray(x)?x[0]:x;
const rname=r=>r.Name||r.PathName||('Raid #'+r.Id);
const pas=t=>String(t||'').split(/[^A-Za-z0-9]+/).filter(Boolean).map(w=>w[0].toUpperCase()+w.slice(1)).join('');
const RIMG={"binah": "data:image/webp;base64,", "chesed": "data:image/webp;base64,", "hieronymus": "data:image/webp;base64,", "goz": "data:image/webp;base64,", "perorodzilla": "data:image/webp;base64,", "gregorius": "data:image/webp;base64,", "hovercraft": "data:image/webp;base64,", "kurokage": "data:image/webp;base64,", "yesod": "data:image/webp;base64,", "drumbarka": "data:image/webp;base64,"};
const rkey=t=>String(t||'').toLowerCase().replace(/[^a-z0-9]/g,'');
const rembed=r=>{const n=rkey(r.Name),p=rkey(r.PathName);let bk=null;try{const b=findBoss(r.Name||r.PathName);bk=b&&(b.k||b.key)}catch(e){}return RIMG[bk]||RIMG[n]||RIMG[p]||(Object.keys(RIMG).find(k=>(n&&n.includes(k))||(p&&p.includes(k)))?RIMG[Object.keys(RIMG).find(k=>(n&&n.includes(k))||(p&&p.includes(k)))]:null)};
let ENM=new Map(),rLearn=null;
const firstArr=d=>{if(Array.isArray(d))return d;for(const k in d||{})if(Array.isArray(d[k]))return d[k];return[]};
async function loadEnemies(){if(ENM.size)return;try{ENM=new Map(firstArr(await fetchJ('enemies.json')).filter(e=>e&&e.Id!=null).map(e=>[e.Id,e]))}catch(e){}}
const eicons=r=>{const ids=[].concat(r.EnemyList||[]).flat(Infinity).filter(x=>typeof x==='number'),out=[];for(const id of ids){const e=ENM.get(id);if(e&&e.Icon&&!out.includes(e.Icon))out.push(e.Icon)}out.sort((x,y)=>(/boss/i.test(y)?1:0)-(/boss/i.test(x)?1:0));return out.slice(0,3)};
window.rOk=el=>{const s=el.currentSrc||el.src||'',m=s.match(/^(https?:\/\/.+?)\/images\/(enemy|raid[a-z\/]*)\/[^\/]+$/i);if(m)rLearn={h:m[1],d:m[2]}};
const rcand=r=>{
  const out=[],seen=new Set(),add=u=>{if(u&&!seen.has(u)){seen.add(u);out.push(u)}};
  const emb=rembed(r);if(emb)add(emb);
  const hosts=[BASE,CDN,RAWH],dirs=['enemy','raid'];
  const urls=f=>{const e=/^[A-Za-z0-9_\-]+$/.test(f)?f:encodeURIComponent(f),o=[];if(rLearn)o.push(`${rLearn.h}/images/${rLearn.d}/${e}.webp`);dirs.forEach(d=>hosts.forEach(h=>o.push(`${h}/images/${d}/${e}.webp`)));return o};
  const files=[...eicons(r)];
  for(const k in r){const v=r[k];if(typeof v==='string'&&/icon|portrait|banner|image|thumb/i.test(k)&&v&&v.length<80)files.push(v.replace(/\.(webp|png|jpg)$/i,''))}
  const pn=String(r.PathName||''),cap=pn?pn[0].toUpperCase()+pn.slice(1):'';
  [cap,pn,pas(r.Name),pas(pn)].forEach(x=>{if(x){files.push('Boss_Portrait_'+x+'_LowRes');files.push('Boss_Portrait_'+x)}});
  files.forEach(f=>urls(f).forEach(add));
  return out;
};
const rsrc=rcand;
const rmono=r=>(pas(rname(r)).slice(0,2)||'?').toUpperCase();
window.rFb=el=>{const c=(el.dataset.c||'').split('|'),i=(+el.dataset.i||0)+1;if(i<c.length){el.dataset.i=i;el.src=c[i]}else{el.onerror=null;const b=document.createElement('b');b.className='mono';b.textContent=el.dataset.m||'?';el.replaceWith(b)}};
function setRimg(el,r){
  const pv=$('rpv');pv.querySelectorAll('.rmono').forEach(x=>x.remove());
  const c=rsrc(r);let i=0;el.style.visibility='visible';
  el.onerror=()=>{if(++i<c.length)el.src=c[i];else{el.onerror=null;el.style.visibility='hidden';const b=document.createElement('b');b.className='rmono';b.textContent=rmono(r);pv.appendChild(b)}};
  el.onload=()=>rOk(el);el.src=c[0]||'';
}

async function ensureRaidsData(){
  if(R_RAW)return R_RAW;
  if(R_RAWp)return R_RAWp;
  R_RAWp=fetchJ('raids.json').then(d=>{
    R_RAW=d;R={};
    for(const k in RC){
      const a=Array.isArray(d[k])?d[k]:[];
      const rel=a.filter(x=>x&&(Array.isArray(x.IsReleased)?x.IsReleased[1]:true));
      R[k]=rel.length?rel:a;
    }
    return d;
  }).catch(e=>{R_RAWp=null;return null});
  return R_RAWp;
}

function findBoss(txt){
  if(txt==null)return null;
  const s=String(txt).trim();if(!s)return null;
  const k=rkey(s);
  if(/^\d+$/.test(s)){
    for(const c in R){
      const hit=(R[c]||[]).find(x=>String(x.Id)===s);
      if(hit)return{name:rname(hit),r:hit,cat:c};
    }
    return null;
  }
  if(k.length<3)return null;
  for(const c in R){
    const hit=(R[c]||[]).find(x=>{
      const kn=rkey(rname(x)),kp=rkey(x.PathName);
      return (kn&&k.includes(kn))||(kp&&k.includes(kp));
    });
    if(hit)return{name:rname(hit),r:hit,cat:c};
  }
  const b=BOSSES.find(x=>x.a.some(al=>k.includes(rkey(al))));
  if(b){
    const hit=(R.Raid||[]).find(x=>rkey(rname(x)).includes(b.k)||rkey(x.PathName).includes(b.k));
    return{name:hit?rname(hit):b.n,r:hit||{Name:b.n,PathName:b.k},cat:'Raid'};
  }
  return null;
}

/* Caelestia Liquid Pill Indicator & Control Center */
function moveDockPill(anim){
  const b=document.querySelector('#csNav .cs-tab.on'),d=$('csPill');
  if(!b||!d)return;
  if(!anim)d.style.transition='none';
  d.style.width=b.offsetWidth+'px';
  d.style.transform=`translateX(${b.offsetLeft}px)`;
  if(!anim){void d.offsetWidth;d.style.transition=''}
  else{
    d.classList.add('stretch');
    setTimeout(()=>d.classList.remove('stretch'),320);
  }
}
if(window.ResizeObserver){
  new ResizeObserver(()=>moveDockPill(false)).observe($('csNav'));
}
addEventListener('resize',()=>moveDockPill(false));

