const PG={home:'pgHome',stu:'pgStu',raid:'pgRaid',evt:'pgEvt'},PO={home:-1,stu:0,raid:1,evt:2};
const PH={home:'Cari…',stu:'Cari murid / sekolah / klub  ( / )',raid:'Cari raid…',evt:'Cari event / raid…'};
let morphO=null;
function morphReveal(to){
  const o=morphO;morphO=null;
  if(!o||!to.animate||REDUCED())return;
  const r=to.getBoundingClientRect(),x=o.x-r.left,y=o.y-r.top,rad=Math.hypot(Math.max(x,r.width-x),Math.max(y,r.height-y))+60;
  to.animate([{clipPath:`circle(0px at ${x}px ${y}px)`},{clipPath:`circle(${rad}px at ${x}px ${y}px)`}],{duration:720,easing:'cubic-bezier(.2,0,0,1)'});
}
document.addEventListener('click',e=>{const tl=e.target.closest&&e.target.closest('.hmt');if(tl&&tileMorph(tl)){morphO=null;return}const t=e.target.closest&&e.target.closest('.hmt,.hml,.cs-tab,.evc,.hmav');if(t){const r=t.getBoundingClientRect();morphO={x:r.left+r.width/2,y:r.top+r.height/2}}},true);

function go(p,instant){
  if(p===page&&!instant)return;
  const from=$(PG[page]),to=$(PG[p]),dir=PO[p]>=PO[page]?1:-1,prev=page;
  page=p;
  document.body.classList.toggle('p-home',p==='home');
  document.body.classList.toggle('p-raid',p==='raid');
  document.body.classList.toggle('p-evt',p==='evt');
  document.querySelectorAll('#csNav .cs-tab').forEach(b=>b.classList.toggle('on',b.dataset.p===p));
  requestAnimationFrame(()=>moveDockPill(true));
  setTimeout(()=>moveDockPill(false),320);
  $('q').value='';$('q').placeholder=PH[p];
  if(p==='home'){document.title='SCHALE DATABASE';history.replaceState(null,'',location.pathname+location.search);renderHome()}
  else if(p==='raid'){document.title='Raid // SCHALE DATABASE';loadRaids()}
  else if(p==='evt'){document.title='Event // SCHALE DATABASE';if(!/^#event/.test(location.hash))history.replaceState(null,'','#event');loadEvents()}
  else{
    document.title=(cur?cur.Name+' // ':'')+'SCHALE DATABASE';
    history.replaceState(null,'',cur?'#'+cur.Id:location.pathname+location.search);
    filter();
  }
  const show=()=>{from.hidden=true;from.classList.remove('out');to.hidden=false;morphReveal(to);to.style.setProperty('--d',dir);to.classList.add('in');setTimeout(()=>to.classList.remove('in'),650);scrollTo({top:0,behavior:'smooth'})};
  if(instant||prev===p){from.hidden=true;to.hidden=false;return}
  from.style.setProperty('--d',dir);from.classList.add('out');
  setTimeout(show,260);
}
function goHash(h){
  if(/^#raid/.test(h)){history.replaceState(null,'',h);go('raid',true)}
  else if(/^#event/.test(h)){history.replaceState(null,'',h);go('evt',true)}
  else if(parseInt(h.slice(1))){go('stu',true)}
}
function pstep(d){if(page==='raid')rstep(d);else if(page==='stu')step(d)}

async function loadRaids(force){
  if(rLoaded&&!force){rfilter();return}
  if(rBusy)return;rBusy=true;
  if(force){R_RAW=null;R_RAWp=null}
  $('rgrid').innerHTML='<div class="sk-load" style="grid-column:1/-1"></div>'.repeat(3);
  try{
    await ensureRaidsData();
    const tot=Object.values(R).reduce((n,a)=>n+a.length,0);
    if(!tot)throw new Error('kosong');
    if(!R[rcat]||!R[rcat].length)rcat=Object.keys(R).find(k=>R[k].length)||rcat;
    await loadEnemies();
    rLoaded=true;
    renderCats();rfilter(true);loadRaidSched();
    const m=location.hash.match(/^#raid-(\w+)-(\d+)/);
    if(m&&R[m[1]]&&R[m[1]].some(x=>x.Id==m[2])){rcat=m[1];renderCats();rfilter();rselect(+m[2])}
    else if(rview.length)rselect(rview[rview.length-1].Id);
  }catch(e){
    $('rgrid').innerHTML='<p class="empty" style="grid-column:1/-1">Gagal mengambil data raid dari SchaleDB. <button class="btn p" onclick="loadRaids(true)">coba lagi</button></p>';
    $('rnm').textContent='Tidak bisa terhubung';
  }finally{rBusy=false}
}
function renderCats(){
  $('rcat').innerHTML=Object.keys(RC).filter(k=>R[k]&&R[k].length).map(k=>`<button data-k="${k}" class="${k===rcat?'on':''}">${RC[k]}</button>`).join('');
}
$('rcat').addEventListener('click',e=>{const b=e.target.closest('button');if(!b||b.dataset.k===rcat)return;beep(880);rcat=b.dataset.k;renderCats();rfilter();if(rview.length)rselect(rview[rview.length-1].Id)});
function rfilter(keep){
  const q=$('q').value.toLowerCase().trim();
  rview=(R[rcat]||[]).filter(r=>!q||[rname(r),r.PathName,r.Faction].join(' ').toLowerCase().includes(q));
  renderRRoster();
}
function renderRRoster(){
  $('rcount').textContent=rview.length+' raid';
  $('rgrid').innerHTML=rview.length?rview.map((r,i)=>{const c=rsrc(r),em=rembed(r),t=(ATK[first(r.BulletType)]||[0,'#0EA5E9'])[1];return `<button class="rc rb${rcur&&rcur.Id===r.Id?' on':''}" data-id="${r.Id}" title="${esc(rname(r))}" style="--n:${Math.min(i,24)};--th:${t}"><img loading="lazy" decoding="async" referrerpolicy="no-referrer" alt="" src="${esc(c[0]||'')}" data-c="${esc(c.join('|'))}" data-m="${esc(rmono(r))}" onload="rOk(this)" onerror="rFb(this)"><span>${esc(rname(r))}</span></button>`}).join(''):'<p class="empty" style="grid-column:1/-1">Tidak ada raid yang cocok.</p>';
}
$('rgrid').addEventListener('click',e=>{const b=e.target.closest('.rc');if(b){beep(780);rselect(+b.dataset.id)}});
$('q').addEventListener('input',()=>{if(page==='raid')rfilter()});

function rmetaHTML(r){
  const rows=[];
  for(const k in r){
    let v=r[k];
    if(v==null||k==='IsReleased')continue;
    if(Array.isArray(v)){if(!v.length||v.some(x=>typeof x==='object'))continue;v=v.join(', ')}
    else if(typeof v==='object')continue;
    else if(typeof v==='boolean')v=v?'Ya':'Tidak';
    const t=String(v);if(!t||t.length>60)continue;
    rows.push(`<div><span>${esc(k.replace(/([a-z])([A-Z])/g,'$1 $2'))}</span><b>${esc(t)}</b></div>`);
    if(rows.length>=24)break;
  }
  return rows.join('')||'<p class="empty">Belum ada data.</p>';
}
function rterrains(r){return (Array.isArray(r.Terrain)?r.Terrain:[r.Terrain]).filter(Boolean).map(t=>typeof t==='string'?t:(t.Terrain||t.Type||'')).filter(Boolean)}
