  const r=(R[rcat]||[]).find(x=>x.Id===id);if(!r)return;
  rcur=r;setShape(id);
  const a=ATK[first(r.BulletType)]||[first(r.BulletType)||'-','#0EA5E9'],ar=ARM[first(r.ArmorType)]||[first(r.ArmorType)||'-','#64748B'],tr=rterrains(r);
