  $('ratk').textContent=a[0];$('ratkP').style.setProperty('--c',a[1]);
  $('rarm').textContent=ar[0];$('rarmP').style.setProperty('--c',ar[1]);
  $('rter').textContent=rterr||'-';
  $('rtabs').innerHTML=tr.length>1?tr.map(t=>`<button data-t="${esc(t)}" class="${t===rterr?'on':''}">${esc(t)}</button>`).join(''):'';
  $('rmeta').innerHTML=rmetaHTML(r);
  $('rpv').classList.remove('swap');void $('rpv').offsetWidth;$('rpv').classList.add('swap');
  $('rinf').classList.remove('sw');void $('rinf').offsetWidth;$('rinf').classList.add('sw');
  setRimg($('rimg'),r);
  if(page==='raid'){history.replaceState(null,'',`#raid-${rcat}-${id}`);document.title=rname(r)+' // SCHALE DATABASE'}
