$('rpv').addEventListener('mousemove',raf(e=>{const r=$('rpv').getBoundingClientRect(),x=(e.clientX-r.left)/r.width-.5,y=(e.clientY-r.top)/r.height-.5;$('rimg').style.setProperty('--ry',x*14+'deg');$('rimg').style.setProperty('--rx',-y*10+'deg')}));
