function efilter(){
  if(!RM)return;
  const q=$('q').value.toLowerCase().trim();
  EV=(eKind==='banner'&&eSrv==='jp'?WK.jp:RM).filter(e=>!isPerm2099(e)&&e.kind===eKind&&(!q||e.name.toLowerCase().includes(q))&&(eStat==='all'||eStatus(e)===eStat));
  renderEvents();
}
function eCard(e,i){
  const st=eStatus(e),[lab,cls]=ESTAT[st],n=Date.now();
  let extra='';
  if(st==='live'&&e.start&&e.end){const pc=Math.max(0,Math.min(100,(n-e.start)/(e.end-e.start)*100));extra=`<div class="evbar"><i style="width:${pc.toFixed(0)}%"></i></div><span class="evleft">Sisa ${leftTxt(e.end-n)}</span>`}
  else if(st==='up'&&e.start){extra=`<span class="evleft">Mulai ${leftTxt(e.start-n)} lagi${e.raw&&e.raw.wiki?'':' · prediksi'}</span>`}
  const rng=e.end?`${eFmt(e.start)} – ${eFmt(e.end)}`:(e.start?eFmt(e.start):'Jadwal belum tersedia');
  const ic=e.kind==='banner'&&e.icon?`<img class="evic" loading="lazy" referrerpolicy="no-referrer" alt="" src="${esc(e.icon)}" onerror="this.style.display='none'">`:'';
  return `<button class="card evc ${cls}" data-id="${esc(e.id)}" style="--h:${hue(e.id)};--n:${Math.min(i,20)}"><div class="evtop"><span class="evid">${KIND[e.kind]||e.kind}${e.rerun?' · Rerun':''}</span><span class="evst">${lab}</span></div><div class="evrow">${ic}<div><b class="evn">${esc(e.name)}</b><small class="evd">${rng}</small></div></div>${extra}</button>`;
}
function renderEvents(){
  $('evcount').textContent=EV.length+' item · '+(eKind==='banner'&&eSrv==='jp'?'jadwal JP (Blue Archive Wiki)':'jadwal Global (belum mulai = prediksi; rerun dari Blue Archive Wiki)')+(WK.ok===false?' · wiki tidak termuat':'');
  if(!EV.length){$('evlist').innerHTML='<p class="empty">Tidak ada data yang cocok.</p>';return}
  const g={live:[],up:[],end:[]};
  EV.forEach(e=>g[eStatus(e)].push(e));
  g.live.sort((a,b)=>a.end-b.end);g.up.sort((a,b)=>a.start-b.start);g.end.sort((a,b)=>(b.end||b.start)-(a.end||a.start));
  const sec=(k,t,big)=>g[k].length?`<section class="evsec"><div class="evsh ${ESTAT[k][1]}"><i></i>${t}<em>${g[k].length}</em></div><div class="evgrid${big?' live':''}">${g[k].map((e,i)=>eCard(e,i)).join('')}</div></section>`:'';
  $('evlist').innerHTML=`<div style="display:grid;gap:22px">${sec('live','Sedang berlangsung',1)}${sec('up','Akan datang',1)}${sec('end','Selesai',0)}</div>`;
}
