/* FLIP Container-Transform Morphing dari Kartu Event ke Modal */
function evOpen(id,srcEl){
  const ev=(RM||[]).concat(WK.jp).find(x=>x.id===String(id));if(!ev)return;
  evAnchor=srcEl||null;window.__evid=ev.id;
  const s=eStatus(ev),[lab,cls]=ESTAT[s];
  const box=$('evbox');
  box.style.setProperty('--h',hue(ev.id));
  const rows=[['Jenis',KIND[ev.kind]||ev.kind],['Mulai',eFmtT(ev.start)],['Selesai',ev.end?eFmtT(ev.end):'-']];
  if(s==='up'&&!(ev.raw&&ev.raw.wiki))rows.push(['Catatan','Prediksi dari jadwal JP. Bisa berubah, digabung, atau dilewati di Global.']);
  const raw=ev.raw;
  for(const k in raw){const v=raw[k];if(v==null||typeof v==='object'||/^(id|kind|name|startDate|endDate|createdAt|updatedAt)$/i.test(k))continue;rows.push([k.replace(/([a-z])([A-Z])/g,'$1 $2'),typeof v==='boolean'?(v?'Ya':'Tidak'):String(v)])}
  const studs=(Array.isArray(raw.students)?raw.students:Array.isArray(raw.pickupStudents)?raw.pickupStudents:[]).map(x=>`<span class="chip">${esc(x.name||sid(x))}${x.isLimitedGlobal?' · Limited':''}${x.isFestGlobal?' · Fest':''}</span>`).join('');
  const hasBoss=ev.kind==='raid'&&findBoss(ev.name);
  const bossBtn=hasBoss?`<button class="btn p" id="evBossBtn" style="margin:10px 0 4px">Lihat Detail Boss Raid →</button>`:'';
  $('evbody').innerHTML=`${ev.kind==='banner'&&ev.icon?`<div class="evban"><img alt="" referrerpolicy="no-referrer" src="${esc(ev.icon.replace('/icons/','/portraits/'))}" data-f="${esc(ev.icon)}" onerror="if(this.dataset.f&&this.src!==this.dataset.f){this.src=this.dataset.f}else{this.parentNode.remove()}"></div>`:''}<span class="evst ${cls}">${lab}</span><h3>${esc(ev.name)}</h3><small class="evd">${ev.end?eFmt(ev.start)+' – '+eFmt(ev.end):eFmt(ev.start)}</small><div class="evcd" id="evcd" hidden></div>${bossBtn}${studs?`<div class="chips" style="margin:10px 0">${studs}</div>`:''}<div class="rmeta">${rows.map(([k,v])=>`<div><span>${esc(k)}</span><b>${esc(v)}</b></div>`).join('')}</div>`;
  const bb=$('evBossBtn');
  if(bb)bb.onclick=()=>{closeEv();go('raid');const m=rmatch(ev.name);if(m){rcat=m.c;renderCats();rfilter();rselect(m.r.Id)}};
  const sr=srcEl?srcEl.getBoundingClientRect():null;
  box.style.transition='none';
  $('evmodal').classList.add('open');
  requestAnimationFrame(()=>{
    const tr=box.getBoundingClientRect();
    if(sr&&tr.width){
      const dx=(sr.left+sr.width/2)-(tr.left+tr.width/2),dy=(sr.top+sr.height/2)-(tr.top+tr.height/2);
      const sx=Math.max(.35,sr.width/tr.width),sy=Math.max(.25,sr.height/tr.height);
      box.style.transform=`translate(${dx}px,${dy}px) scale(${sx},${sy})`;
      box.style.borderRadius='26px';
      box.style.opacity='.6';
    }else{
      box.style.transform='translateY(48px) scale(.9)';
      box.style.opacity='0';
    }
    void box.offsetWidth;
    box.style.transition='';
    box.style.transform='none';
    box.style.borderRadius='34px';
    box.style.opacity='1';
  });
  history.replaceState(null,'','#event-'+encodeURIComponent(ev.id));
  clearInterval(evTimer);
  const target=s==='up'?ev.start:(s==='live'?ev.end:0);
  if(target){const t=()=>{let d=Math.max(0,target-Date.now());const D=Math.floor(d/864e5);d%=864e5;const H=Math.floor(d/36e5);d%=36e5;const M=Math.floor(d/6e4),S=Math.floor(d%6e4/1e3),c=$('evcd');if(!c)return;c.hidden=false;c.innerHTML=[[D,'hari'],[H,'jam'],[M,'menit'],[S,'detik']].map(([v,l])=>`<div><b>${v}</b><span>${l}</span></div>`).join('')};t();evTimer=setInterval(t,1000)}
}
function closeEv(){
  if(!$('evmodal').classList.contains('open'))return;
  const box=$('evbox');
  if(evAnchor&&document.body.contains(evAnchor)){
    const sr=evAnchor.getBoundingClientRect(),tr=box.getBoundingClientRect();
    const dx=(sr.left+sr.width/2)-(tr.left+tr.width/2),dy=(sr.top+sr.height/2)-(tr.top+tr.height/2);
    box.style.transform=`translate(${dx}px,${dy}px) scale(${Math.max(.35,sr.width/tr.width)},${Math.max(.25,sr.height/tr.height)})`;
    box.style.opacity='0';
  }else{
    box.style.transform='translateY(40px) scale(.92)';
    box.style.opacity='0';
  }
  $('evmodal').classList.remove('open');
  clearInterval(evTimer);
  if(page==='evt')history.replaceState(null,'','#event');
}
$('evx').onclick=closeEv;
