/* ===== Efek morph & mode hemat ===== */
const REDUCED=()=>matchMedia('(prefers-reduced-motion: reduce)').matches||document.documentElement.classList.contains('lite');
const EASE='cubic-bezier(.2,0,0,1)';
function tileMorph(t){
  if(!t.animate||REDUCED())return false;
  const r=t.getBoundingClientRect(),cs=getComputedStyle(t),o=document.createElement('div');
  o.style.cssText=`position:fixed;z-index:200;left:${r.left}px;top:${r.top}px;width:${r.width}px;height:${r.height}px;border-radius:${cs.borderRadius};background-image:${cs.backgroundImage};background-color:${cs.backgroundColor};pointer-events:none`;
  document.body.appendChild(o);
  const a=o.animate([{left:r.left+'px',top:r.top+'px',width:r.width+'px',height:r.height+'px',borderRadius:cs.borderRadius},{left:'0px',top:'0px',width:'100vw',height:'100vh',borderRadius:'0px'}],{duration:480,easing:EASE,fill:'forwards'});
  a.onfinish=()=>{const f=o.animate([{opacity:1},{opacity:0}],{duration:440,delay:120,easing:'ease-out',fill:'forwards'});f.onfinish=()=>o.remove()};
  setTimeout(()=>o.remove(),2500);
  return true;
}
function themeSwap(fn,btn){
  if(!document.startViewTransition||REDUCED()){fn();return}
  const r=btn.getBoundingClientRect(),x=r.left+r.width/2,y=r.top+r.height/2,rad=Math.hypot(Math.max(x,innerWidth-x),Math.max(y,innerHeight-y));
  const vt=document.startViewTransition(fn);
  vt.ready.then(()=>document.documentElement.animate({clipPath:[`circle(0px at ${x}px ${y}px)`,`circle(${rad}px at ${x}px ${y}px)`]},{duration:720,easing:EASE,pseudoElement:'::view-transition-new(root)'})).catch(()=>{});
}
