/* ===== Banner dari Blue Archive Wiki (Filter 2099 aktif) ===== */
const WK={gl:[],jp:[],ok:null};let eSrv='gl';
const WIKI='https://bluearchive.wiki/w/api.php';
async function wikiBanners(page){
  const r=await fetch(`${WIKI}?action=parse&format=json&formatversion=2&prop=text&redirects=1&origin=*&page=${encodeURIComponent(page)}`);
  if(!r.ok)throw new Error(r.status);
  const html=((await r.json()).parse||{}).text;if(!html)throw new Error('kosong');
  const doc=new DOMParser().parseFromString(html,'text/html'),out=[];
  const re=/(\d{4})\/(\d{2})\/(\d{2})\s+(\d{2}):(\d{2})\s*[–—-]\s*(\d{4})\/(\d{2})\/(\d{2})\s+(\d{2}):(\d{2})/;
  const T=c=>c.textContent.replace(/\s+/g,' ').trim();
  doc.querySelectorAll('tr').forEach(tr=>{
    const td=[...tr.children];if(td.length<2)return;
    const per=td.map(c=>T(c).match(re)).find(Boolean);if(!per)return;
    const ts=(y,mo,d,hh,mi)=>Date.UTC(+y,+mo-1,+d,+hh-9,+mi);
    const start=ts(...per.slice(1,6)),end=ts(...per.slice(6,11))+6e4;
    if(isPerm2099({start,end}))return;
    let names=[],cell=null;
    for(const c of td){if(re.test(T(c)))continue;const n=[...c.querySelectorAll('a')].map(T).filter(t=>t&&!/^(rerun|anniversary|limited|file:)/i.test(t));if(n.length){names=[...new Set(n)];cell=c;break}}
    if(!names.length)return;
    out.push({names,start,end,rerun:/rerun/i.test(T(cell))});
  });
  return out;
}
const wkItem=(w,srv)=>{const st=S.find(s=>nrm(s.Name)===nrm(w.names[0]));return{id:'w'+srv+w.start+'_'+h32(w.names.join()),kind:'banner',name:w.names.join(', '),start:w.start,end:w.end,icon:st?img(st.Id,'icon'):'',rerun:w.rerun,srv,raw:{students:w.names.map(n=>({name:n})),wiki:{},sumber:'Blue Archive Wiki'}}};
let wkP=null;
function loadWiki(){
  if(wkP)return wkP;
  const pages={gl:['Banner_List_(Global)/Banners_of_2026'],jp:['Banner_List/Banners_of_2026']};
  wkP=Promise.all(['gl','jp'].map(async srv=>{
    const arr=[];let ok=false;
    for(const p of pages[srv]){try{(await wikiBanners(p)).forEach(w=>arr.push(wkItem(w,srv)));ok=true}catch(e){}}
    return[srv,arr.filter(x=>!isPerm2099(x)),ok]
  })).then(res=>{res.forEach(([srv,arr])=>{WK[srv]=arr});WK.ok=res.some(r=>r[2]);mergeWikiGlobal();return WK});
  return wkP;
}
function mergeWikiGlobal(){
  if(!RM)return;
  const base=RM.filter(x=>!(x.raw&&x.raw.wiki)&&!isPerm2099(x)),nm=x=>((x.raw&&x.raw.students)||[]).map(s=>nrm(s.name));
  const extra=WK.gl.filter(w=>!isPerm2099(w)&&!base.some(b=>b.kind==='banner'&&Math.abs(b.start-w.start)<36e5*36&&nm(b).some(n=>nm(w).includes(n))));
  RM=base.concat(extra);
}

/* ===== Skill bahasa Inggris (dari ba.joexyz.online) ===== */
const hasJP=s=>{const k=(s&&s.Skills)||{};return /[\u3040-\u30ff\u3400-\u9fff]/.test([k.Ex&&k.Ex.Name,k.Ex&&k.Ex.Desc,k.Public&&k.Public.Name,k.Passive&&k.Passive.Name].join(' '))};
function convSkills(d){
  const out={},sk=(d&&d.data&&d.data.skills)||[];
  const slot=t=>{t=String(t||'').toLowerCase();return t==='ex'?'Ex':/sub|extra/.test(t)?'ExtraPassive':/passive/.test(t)?'Passive':/normal|public|basic/.test(t)?'Public':null};
  sk.filter(x=>!x.upgradeOfId&&!x.parentId).sort((a,b)=>(a.sortOrder||0)-(b.sortOrder||0)).forEach(x=>{
    const k=slot(x.type);if(!k||out[k])return;
    const n=x.maxLevel||5,tl=x.templates||[],tpl=tl[(x.levelTemplates||[])[n-1]??0]||tl[0]||'';
    const np=Math.max(0,...(x.params||[]).map(p=>p.length)),Parameters=[];
    for(let i=0;i<np;i++)Parameters.push((x.params||[]).map(p=>p[i]??''));
    const cv=t=>String(t||'').replace(/\{\{/g,'\u0001').replace(/\{p:(\d+)\}/g,(m,i)=>`<?${+i+1}>`).replace(/\{d:[^}]*\}/g,'').replace(/\{\/?[es](?::[^}]*)?\}/g,'').replace(/\u0001/g,'{').replace(/\s*\n\s*/g,' ');
    const desc=cv(tpl),Descs=[];for(let i=0;i<n;i++)Descs.push(cv(tl[(x.levelTemplates||[])[i]??0]||tpl));
    out[k]={Name:x.name,Desc:desc,Descs,Parameters,Cost:x.costs&&x.costs.length?x.costs:undefined,Icon:x.iconUrl||''};
  });
  return out;
}
async function ensureEnSkills(s){
  if(!s||s._enTried||!(s._x||hasJP(s)))return;
  s._enTried=true;
  try{
    let slug=s._slug;
    if(!slug){
      if(!extList){const r=await fetch(API+'/students?limit=500');extList=(await r.json()).data||[];extAt=Date.now()}
      const m=extList.find(e=>nrm(e.name)===nrm(s.Name));slug=m?m.id:String(s.Id);
    }
    const r=await fetch(`${API}/students/${encodeURIComponent(slug)}/skills?locale=en`);if(!r.ok)throw new Error(r.status);
    const sk=convSkills(await r.json());
    if(Object.keys(sk).length){s.Skills=sk;if(cur===s)renderSkills()}
  }catch(e){}
}

